import esbuild from "esbuild";
import { createPluginBundlerPresets } from "@paperclipai/plugin-sdk/bundlers";

// This plugin has no UI bundle: its settings form is generated by the host
// from `instanceConfigSchema` in the manifest.
const presets = createPluginBundlerPresets({});
const watch = process.argv.includes("--watch");

/**
 * `pg` is left out of the bundle, not bundled in.
 *
 * It is CommonJS and reaches for `require("events")` at load time. esbuild
 * cannot turn that into an ESM import, so it emits a stub that throws
 * `Dynamic require of "events" is not supported` — and because the throw
 * happens while the module graph is loading, the worker dies before the host's
 * first RPC. `scripts/smoke.mjs` is what catches this; it did.
 *
 * Marking it external means Node resolves it from `node_modules` at runtime,
 * which is exactly what happens in a deployed install: the host npm-installs
 * this package, and `pg` is a declared runtime dependency.
 */
const workerConfig = {
  ...presets.esbuild.worker,
  external: [...(presets.esbuild.worker.external ?? []), "pg", "pg-native"],
};

const workerCtx = await esbuild.context(workerConfig);
const manifestCtx = await esbuild.context(presets.esbuild.manifest);

if (watch) {
  await Promise.all([workerCtx.watch(), manifestCtx.watch()]);
  console.log("esbuild watch mode enabled for worker and manifest");
} else {
  await Promise.all([workerCtx.rebuild(), manifestCtx.rebuild()]);
  await Promise.all([workerCtx.dispose(), manifestCtx.dispose()]);
}
